"""Create a epilog string for the specified commands.

    Args:
        commands: Sequence of (func, name, description)

    Returns:
        str: Formatted list of commands and their descriptions
    """
def _format_epilog(commands: Any) -> object {
    lines = [];
    lines.append("Commands:");
    for command in commands {
        name = command[1];
        desc = command[2] or " ";
        for (index, item) in enumerate(desc.splitlines()) {
            item = item.strip();
            if (index == 0) {
                line = "  %-16s%s" % (name, item);
            } else {
                line = (" " * 18) + item;
            }
            lines.append(line);
        }
    }
    return '\r\n'.join(lines);
}

"""
    overpython.subt(intf, ints)

    Subtract intf with ints. Raises ValueError if intf/ints is a string.
    """
def subt(intf: Any, ints: Any) -> object {
    try {
        return (float(intf) - float(ints));
    } except ValueError {
        raise ValueError(("%s/%s is not a number" % (intf, ints)));
    }
}

