"""
    Utility function to remove duplicates from a list
    :param seq: The sequence (list) to deduplicate
    :return: A list with original duplicates removed
    """
def dedupe_list(seq: Any) -> object {
    seen = `set();
    return [
        x
        for x in seq
        if not ((x in seen) or seen.add(x))
    ];
}

"""
    Colors elements in a dateframe
    green if positive and red if
    negative. Does not color NaN
    values.
    """
def color_negative_red(value: Any) -> object {
    if (value < 0) {
        color = "red";
    } elif (value > 0) {
        color = "green";
    } else {
        color = "black";
    }
    return ("color: %s" % color);
}

